def readable_rows(rows,principal,grants):
    return [row for row in rows if (principal,row['tenant_id'],row['document_id'],row['document_version']) in grants]

def authorized_topk(rows,principal,grants,k,score):
    if type(k) is not int or k<1:
        raise ValueError("positive exact-int k required")
    allowed=readable_rows(rows,principal,grants)
    if not allowed:
        return []
    if k>len(allowed):
        raise ValueError("k exceeds authorized count")
    scored=[(row['chunk_id'],score(row)) for row in allowed]
    return [x[0] for x in sorted(scored,key=lambda x:(-x[1],x[0]))[:k]]

