import hashlib,re
def initial_chunk(record):
    fields={'tenant_id','document_id','document_version','title','text'}
    if not isinstance(record,dict) or set(record)!=fields or any(not isinstance(x,str) for x in record.values()):
        raise ValueError("exact string fields required")
    parts=[record[k] for k in ('tenant_id','document_id','document_version')]
    if any(re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9._-]{0,127}',x) is None for x in parts):
        raise ValueError("invalid source identity")
    for key,limit in [('title',200),('text',1000)]:
        value=record[key]
        if not value.strip() or len(value)>limit:
            raise ValueError("invalid source text size")
        try:
            value.encode('utf-8')
        except UnicodeEncodeError as exc:
            raise ValueError("invalid UTF-8 text") from exc
    return {'chunk_id':':'.join(parts)+':0','tenant_id':parts[0],'document_id':parts[1],
            'document_version':parts[2],'text':record['text'],
            'content_digest':hashlib.sha256(record['text'].encode('utf-8')).hexdigest()}

import hashlib
def embedding_fingerprint(identity):
    fields=('model_id','artifact_digest','runtime_version','preprocessing_version','dimension','metric','asymmetric')
    material=chr(31).join(str(identity[k]) for k in fields)
    return hashlib.sha256(material.encode('utf-8')).hexdigest()

