def exact_search(query,rows,k):
    q=unit_vector(query)
    if type(k) is not int or k<1:
        raise ValueError("positive exact-int k required")
    if not rows:
        return []
    if k>len(rows):
        raise ValueError("k exceeds candidate count")
    scored=[]
    for row in rows:
        v=unit_vector(row['vector'])
        if len(v)!=len(q):
            raise ValueError("dimension mismatch")
        score=max(-1.0,min(1.0,math.fsum(a*b for a,b in zip(q,v))))
        scored.append((row['chunk_id'],score))
    return sorted(scored,key=lambda x:(-x[1],x[0]))[:k]

